(function () {
  "use strict";

  if (window.__FIESTIKA_RULETA_INITIALIZED__) {
    return;
  }

  window.__FIESTIKA_RULETA_INITIALIZED__ = true;

  var APP = {
    WHATSAPP_NUMBER: "51926601630",
    GOOGLE_SCRIPT_URL:
      "https://script.google.com/macros/s/AKfycbx7kTnN2oB4bAZX_YTQgaZXqzNW9cdH5tloWURbtvQmQffBdqi8IjvbpjI1HpIYbZiE/exec",

    // Se mantiene casi imposible.
    DELIVERY_GRATIS_WEIGHT: 0.001,

    prizes: [
  {
    label: "5 Toppers",
    lines: ["5", "TOPPERS"],
    message: "Te ganaste 5 Toppers",
    weight: 45,
    color: "#fdeeea"
  },
  {
    label: "1 gorro de cumpleaños",
    lines: ["1 GORRO", "CUMPLEAÑOS"],
    message: "Te ganaste 1 gorro de cumpleaños",
    weight: 35,
    color: "#dff7ef"
  },
  {
    label: "5 maxi toppers + gorrito de cumpleaños",
    lines: ["5 MAXI", "+ GORRITO"],
    message: "Te ganaste 5 maxi topper + gorrito de cumpleaños",
    weight: 12,
    color: "#fff0c9"
  },
  {
    label: "1 Cake topper 3D",
    lines: ["CAKE", "TOPPER 3D"],
    message: "Te ganaste 1 Cake topper 3D",
    weight: 8,
    color: "#eee7ff"
  },
  {
    label: "Delivery gratis",
    lines: ["DELIVERY", "GRATIS"],
    message: "Te ganaste Delivery gratis",
    weight: 0.001,
    color: "#ffe4ee"
  },
  {
    label: "20% dscto en tu siguiente pedido",
    lines: ["20% DSCTO", "SIG. PEDIDO"],
    message: "Te ganaste 20% dscto en tu siguiente pedido",
    weight: 0.001,
    color: "#fce6f0"
  }
],

    rotation: 0,
    spinning: false
  };
  
  APP.segmentAngle = (Math.PI * 2) / APP.prizes.length;

  var elements = {
    canvas: document.getElementById("wheel"),
    spinBtn: document.getElementById("spinBtn"),
    spinCenter: document.getElementById("spinCenter"),
    statusBox: document.getElementById("status"),
    codeInput: document.getElementById("clientCode"),
    modal: document.getElementById("modal"),
    modalTitle: document.getElementById("modalTitle"),
    prizeName: document.getElementById("prizeName"),
    codeResult: document.getElementById("codeResult"),
    whatsappLink: document.getElementById("whatsappLink"),
    closeModal: document.getElementById("closeModal")
  };

  if (
    !elements.canvas ||
    !elements.spinBtn ||
    !elements.spinCenter ||
    !elements.statusBox ||
    !elements.codeInput ||
    !elements.modal ||
    !elements.prizeName ||
    !elements.codeResult ||
    !elements.whatsappLink ||
    !elements.closeModal
  ) {
    console.error("No se encontraron todos los elementos HTML de la ruleta.");
    return;
  }

  APP.ctx = elements.canvas.getContext("2d");

  function normalizeCode(value) {
    return String(value || "")
      .trim()
      .toUpperCase()
      .replace(/\s+/g, "-");
  }

  function getCode() {
    return normalizeCode(elements.codeInput.value);
  }

  function findPrizeByLabel(label) {
    var normalized = String(label || "").trim().toUpperCase();

    for (var i = 0; i < APP.prizes.length; i += 1) {
      if (APP.prizes[i].label.toUpperCase() === normalized) {
        return APP.prizes[i];
      }
    }

    return null;
  }

  function callGoogleSheetSpin(code, callback) {
    var callbackName =
      "fiestikaCallback_" +
      Date.now() +
      "_" +
      Math.floor(Math.random() * 100000);

    var jsonpScript = document.createElement("script");
    var timeoutId;

    window[callbackName] = function (response) {
      clearTimeout(timeoutId);

      callback(response);

      delete window[callbackName];

      if (jsonpScript.parentNode) {
        jsonpScript.parentNode.removeChild(jsonpScript);
      }
    };

    jsonpScript.onerror = function () {
      clearTimeout(timeoutId);

      callback({
        ok: false,
        status: "CONNECTION_ERROR",
        message:
          "No se pudo conectar con la base de códigos. Intenta nuevamente."
      });

      delete window[callbackName];

      if (jsonpScript.parentNode) {
        jsonpScript.parentNode.removeChild(jsonpScript);
      }
    };

    timeoutId = setTimeout(function () {
      callback({
        ok: false,
        status: "TIMEOUT",
        message: "La validación del código está demorando. Intenta nuevamente."
      });

      delete window[callbackName];

      if (jsonpScript.parentNode) {
        jsonpScript.parentNode.removeChild(jsonpScript);
      }
    }, 12000);

    jsonpScript.src =
      APP.GOOGLE_SCRIPT_URL +
      "?code=" +
      encodeURIComponent(code) +
      "&callback=" +
      encodeURIComponent(callbackName) +
      "&t=" +
      Date.now();

    document.body.appendChild(jsonpScript);
  }

  function setReadyState() {
    APP.spinning = false;
    elements.spinBtn.disabled = false;
    elements.spinCenter.style.pointerEvents = "auto";
    elements.spinCenter.style.opacity = "1";
    elements.statusBox.textContent =
      "Código listo. Toca la ruleta o el botón para girar.";
  }

  function setEmptyState() {
    APP.spinning = false;
    elements.spinBtn.disabled = false;
    elements.spinCenter.style.pointerEvents = "auto";
    elements.spinCenter.style.opacity = "1";
    elements.statusBox.textContent = "Coloca tu código para activar tu giro.";
  }

  function setLockedState(data) {
    APP.spinning = false;
    elements.spinBtn.disabled = true;
    elements.spinCenter.style.pointerEvents = "none";
    elements.spinCenter.style.opacity = "0.72";

    elements.statusBox.innerHTML =
      "Este código ya fue usado.<br><strong>Premio registrado:</strong> " +
      (data.prize || "No registrado");
  }

  function checkCodeState() {
    var code = getCode();

    if (!code) {
      setEmptyState();
      return;
    }

    setReadyState();
  }

  function drawWheel() {
    var ctx = APP.ctx;
    var w = elements.canvas.width;
    var h = elements.canvas.height;
    var cx = w / 2;
    var cy = h / 2;
    var radius = w * 0.45;

    ctx.clearRect(0, 0, w, h);

    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(APP.rotation);

    APP.prizes.forEach(function (prize, index) {
      var start = -Math.PI / 2 - APP.segmentAngle / 2 + index * APP.segmentAngle;
      var end = start + APP.segmentAngle;

      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.arc(0, 0, radius, start, end);
      ctx.closePath();
      ctx.fillStyle = prize.color;
      ctx.fill();

      ctx.lineWidth = 8;
      ctx.strokeStyle = "rgba(255,255,255,.9)";
      ctx.stroke();

      ctx.save();
      ctx.rotate(start + APP.segmentAngle / 2);
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillStyle = "#50485d";
      ctx.font = "900 34px Inter, system-ui, sans-serif";

      prize.lines.forEach(function (line, lineIndex) {
        ctx.fillText(
          line,
          radius * 0.62,
          (lineIndex - (prize.lines.length - 1) / 2) * 38
        );
      });

      ctx.restore();
    });

    ctx.beginPath();
    ctx.arc(0, 0, radius + 8, 0, Math.PI * 2);
    ctx.lineWidth = 12;
    ctx.strokeStyle = "rgba(255,255,255,.96)";
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(0, 0, radius * 0.18, 0, Math.PI * 2);
    ctx.fillStyle = "rgba(255,255,255,.94)";
    ctx.fill();

    ctx.restore();
  }

  function normalizeAngle(angle) {
    var full = Math.PI * 2;
    return ((angle % full) + full) % full;
  }

  function easeOutCubic(t) {
    return 1 - Math.pow(1 - t, 3);
  }

  function launchConfetti() {
    var colors = ["#f45f8e", "#ffbd6f", "#9ce1d1", "#ad91ee", "#fdeeea"];

    for (var i = 0; i < 90; i += 1) {
      (function (index) {
        var piece = document.createElement("div");

        piece.className = "confetti-piece";
        piece.style.left = Math.random() * 100 + "vw";
        piece.style.background =
          colors[Math.floor(Math.random() * colors.length)];
        piece.style.animationDuration = 2.4 + Math.random() * 2.4 + "s";
        piece.style.animationDelay = Math.random() * 0.25 + "s";
        piece.style.transform = "rotate(" + Math.random() * 180 + "deg)";

        document.body.appendChild(piece);

        setTimeout(function () {
          piece.remove();
        }, 5200 + index * 3);
      })(i);
    }
  }

  function showResult(data) {
    if (elements.modalTitle) {
      elements.modalTitle.textContent = "¡Felicidades!";
    }

    elements.prizeName.textContent = data.message;
    elements.codeResult.textContent = "Código: " + data.code;

    elements.whatsappLink.style.display = "inline-flex";

    var text =
      "Hola Fiestika, giré la ruleta y gané: " +
      data.prize +
      ". Mi código es: " +
      data.code +
      ".";

    elements.whatsappLink.href =
      "https://wa.me/" +
      APP.WHATSAPP_NUMBER +
      "?text=" +
      encodeURIComponent(text);

    elements.modal.classList.add("show");
  }

  function showAlreadyUsed(data) {
    if (elements.modalTitle) {
      elements.modalTitle.textContent = "Código ya usado";
    }

    elements.prizeName.textContent = "Este código ya fue usado";
    elements.codeResult.textContent = data.prize
      ? "Premio registrado: " + data.prize
      : "Código: " + data.code;

    elements.whatsappLink.style.display = "none";
    elements.modal.classList.add("show");
  }

  function showInvalidCode(message) {
    if (elements.modalTitle) {
      elements.modalTitle.textContent = "Código no válido";
    }

    elements.prizeName.textContent = message || "Este código no está disponible";
    elements.codeResult.textContent = "";
    elements.whatsappLink.style.display = "none";
    elements.modal.classList.add("show");
  }

  function closeResult() {
    elements.modal.classList.remove("show");
    elements.whatsappLink.style.display = "inline-flex";
  }

  function animateToPrize(prize, code, responseData) {
    var prizeIndex = APP.prizes.indexOf(prize);
    var full = Math.PI * 2;
    var current = normalizeAngle(APP.rotation);
    var target = normalizeAngle(-prizeIndex * APP.segmentAngle);
    var delta = target - current;

    if (delta < 0) {
      delta += full;
    }

    var turns = 7 + Math.floor(Math.random() * 3);
    var startRotation = APP.rotation;
    var finalRotation = APP.rotation + turns * full + delta;
    var duration = 5200;
    var startTime = performance.now();

    APP.spinning = true;
    elements.spinBtn.disabled = true;
    elements.spinCenter.style.pointerEvents = "none";
    elements.statusBox.textContent = "Girando... preparando tu premio ✨";

    function animate(now) {
      var elapsed = now - startTime;
      var progress = Math.min(elapsed / duration, 1);

      APP.rotation =
        startRotation + (finalRotation - startRotation) * easeOutCubic(progress);

      drawWheel();

      if (progress < 1) {
        requestAnimationFrame(animate);
        return;
      }

      APP.rotation = finalRotation;
      drawWheel();

      APP.spinning = false;

      var data = {
        code: code,
        prize: prize.label,
        message:
          responseData && responseData.message
            ? responseData.message
            : prize.message,
        createdAt: new Date().toISOString()
      };

      setLockedState(data);
      launchConfetti();
      showResult(data);
    }

    requestAnimationFrame(animate);
  }

  function spin() {
    if (APP.spinning) {
      return;
    }

    var code = getCode();

    if (!code) {
      elements.statusBox.textContent = "Primero ingresa tu código temporal.";
      elements.codeInput.focus();
      return;
    }

    APP.spinning = true;
    elements.spinBtn.disabled = true;
    elements.spinCenter.style.pointerEvents = "none";
    elements.statusBox.textContent = "Validando tu código...";

    callGoogleSheetSpin(code, function (response) {
      APP.spinning = false;

      if (!response || !response.ok) {
        elements.spinBtn.disabled = false;
        elements.spinCenter.style.pointerEvents = "auto";

        var errorMessage =
          response && response.message
            ? response.message
            : "No se pudo validar el código.";

        elements.statusBox.textContent = errorMessage;
        showInvalidCode(errorMessage);
        return;
      }

      if (response.status === "ALREADY_USED") {
        var usedData = {
          code: response.code || code,
          prize: response.prize || "",
          message: "Este código ya fue usado",
          createdAt: new Date().toISOString()
        };

        setLockedState(usedData);
        showAlreadyUsed(usedData);
        return;
      }

      if (response.status !== "WINNER") {
        elements.spinBtn.disabled = false;
        elements.spinCenter.style.pointerEvents = "auto";

        var unavailableMessage =
          response.message || "Este código no está disponible.";

        elements.statusBox.textContent = unavailableMessage;
        showInvalidCode(unavailableMessage);
        return;
      }

      var prize = findPrizeByLabel(response.prize);

      if (!prize) {
        elements.spinBtn.disabled = false;
        elements.spinCenter.style.pointerEvents = "auto";

        var mismatchMessage =
          "El premio recibido no coincide con la ruleta: " + response.prize;

        elements.statusBox.textContent = mismatchMessage;
        showInvalidCode(mismatchMessage);
        return;
      }

      animateToPrize(prize, response.code || code, response);
    });
  }

  function runSilentTests() {
    var tests = [
      {
        name: "normaliza código",
        ok: normalizeCode(" fiestika 001 ") === "FIESTIKA-001"
      },
      {
        name: "encuentra premio",
        ok: !!findPrizeByLabel("5 toppers")
      },
      {
        name: "delivery casi imposible",
        ok: APP.DELIVERY_GRATIS_WEIGHT === 0.001
      },
      {
        name: "url google script configurada",
        ok: APP.GOOGLE_SCRIPT_URL.indexOf("script.google.com") !== -1
      }
    ];

    tests.forEach(function (test) {
      if (!test.ok) {
        console.warn("Fiestika Ruleta test falló:", test.name);
      }
    });
  }

  var queryCode = new URLSearchParams(window.location.search).get("code");

  if (queryCode) {
    elements.codeInput.value = normalizeCode(queryCode);
    elements.codeInput.readOnly = true;
  }

  elements.spinBtn.addEventListener("click", spin);
  elements.spinCenter.addEventListener("click", spin);
  elements.canvas.addEventListener("click", spin);

  elements.closeModal.addEventListener("click", closeResult);

  elements.modal.addEventListener("click", function (event) {
    if (event.target === elements.modal) {
      closeResult();
    }
  });

  elements.codeInput.addEventListener("input", checkCodeState);

  drawWheel();
  checkCodeState();
  runSilentTests();

  window.FiestikaRouletteApp = {
    normalizeCode: normalizeCode,
    findPrizeByLabel: findPrizeByLabel,
    callGoogleSheetSpin: callGoogleSheetSpin,
    spin: spin
  };
})();